#define rot(a) mat2(cos(a+vec4(0,11,33,0)))

//formula for creating colors;
#define H(h)  (  cos( h*6. + 5.*vec3(1,2,3) )*.6 + .4 )

//formula for mapping scale factor 
#define M(c)  log(1.+c)

#define R iResolution

void mainImage( out vec4 O, vec2 U) {


    float wfac = .9;

    O = vec4(0); 
    vec3 c=vec3(0);  
    vec4 rd = normalize( vec4(U-.5*R.xy, .8*R.y, wfac*R.y)); 

    float sc,dotp,totdist=0., t=iTime/5.; 

    for (float i=0.; i<100.; i++) {

        vec4 p = vec4( rd*totdist ) * 15.;

        p -= .2;
        p.zw *= rot( t );
        p.xw *= rot( t/2. );
        p.xz *= rot( t/5. );

        sc = 1.;  
        vec4 w = p;

        for (float j=0.; j<15.; j++) {

            p = abs( p - .75 ) * 1.1;

            p.xz *= rot(.2);
            p.zw *= rot(.2);
            p.yw *= rot(.1);

            sc *= length(p)/length(w);

            w = p;

        }

        float dist = clamp(abs( length(p) - 1.)/(1.+sc),1e-5,.2) ; 
        float stepsize = dist/10. + 4e-4  ;
        totdist += stepsize;    

        c += .2 * H(M(sc)) * exp(-i*i*stepsize*stepsize*1e3);


    }

    c = clamp(c,-100.,100.);

    c = 1. - exp(-c*c);

    c *= exp(-totdist*totdist/2.);

    c.b *= 1.5;

    O = ( vec4(c,0) );

}
